    out << "vector3f physics:angularVelocity = (4.2380407e-7, 0.0000028553638, 0.000013044848)" << std::endl;
    out << "vector3f physics:velocity = (-0.0000017047057, 7.286984e-8, 3.154851e-7)" << std::endl;
    Eigen::Quaterniond q(mat_AttachToolAdaptor.topLeftCorner<3, 3>());
    q.normalize();
    out << "quatf xformOp:orient = (" << q.w() << ", " << q.x() << ", " << q.y() << ", " << q.z() << ")" << std::endl;
    out << "float3 xformOp:scale = (1, 1, 1)" << std::endl;
    Eigen::Vector3d t(mat_AttachToolAdaptor.block<3, 1>(0, 3));
    out << "double3 xformOp:translate = (" << t.x() << ", " << t.y() << ", " << t.z() << ")" << std::endl;
    out << "uniform token[] xformOpOrder = [\"xformOp:translate\", \"xformOp:orient\", \"xformOp:scale\"]" << std::endl;
    out << "" << std::endl;
    out << "def Mesh \"Mesh\" (" << std::endl;
