void USDA_writer::write_json_jointstate(const std::string &filename, const std::vector<double> &joint_pos)
{
    std::ofstream out(filename);
    out.precision(15);
    out << "{" << std::endl;
    out << "    \"joint_target\": [" << std::endl;
    for(size_t i=0; i<6; i++)
    {
        if(i != 5)
            out << "        " << joint_pos[i] << "," << std::endl;
        else
            out << "        " << joint_pos[i] << std::endl;
    }
    out << "    ]" << std::endl;
    out << "}" << std::endl;
    out.close();
}